// NewRegistryServiceHandler builds an HTTP handler from the service implementation. It returns the
// path on which to mount the handler and the handler itself.
//
// By default, handlers support the Connect, gRPC, and gRPC-Web protocols with the binary Protobuf
// and JSON codecs. They also support gzip compression.
func NewRegistryServiceHandler(svc RegistryServiceHandler, opts ...connect.HandlerOption) (string, http.Handler) {
	registryServiceMethods := v1.File_easylab_v1_easylab_proto.Services().ByName("RegistryService").Methods()
	registryServiceListPackageTypesHandler := connect.NewUnaryHandler(
		RegistryServiceListPackageTypesProcedure,
		svc.ListPackageTypes,
		connect.WithSchema(registryServiceMethods.ByName("ListPackageTypes")),
		connect.WithHandlerOptions(opts...),
	)
	registryServiceListPackagesHandler := connect.NewUnaryHandler(
		RegistryServiceListPackagesProcedure,
		svc.ListPackages,
		connect.WithSchema(registryServiceMethods.ByName("ListPackages")),
		connect.WithHandlerOptions(opts...),
	)
	registryServicePackageVersionsHandler := connect.NewUnaryHandler(
		RegistryServicePackageVersionsProcedure,
		svc.PackageVersions,
		connect.WithSchema(registryServiceMethods.ByName("PackageVersions")),
		connect.WithHandlerOptions(opts...),
	)
	registryServiceDeletePackageHandler := connect.NewUnaryHandler(
		RegistryServiceDeletePackageProcedure,
		svc.DeletePackage,
		connect.WithSchema(registryServiceMethods.ByName("DeletePackage")),
		connect.WithHandlerOptions(opts...),
	)
	registryServiceDeletePackageVersionHandler := connect.NewUnaryHandler(
		RegistryServiceDeletePackageVersionProcedure,
		svc.DeletePackageVersion,
		connect.WithSchema(registryServiceMethods.ByName("DeletePackageVersion")),
		connect.WithHandlerOptions(opts...),
	)
	registryServiceListPublishSpecsHandler := connect.NewUnaryHandler(
		RegistryServiceListPublishSpecsProcedure,
		svc.ListPublishSpecs,
		connect.WithSchema(registryServiceMethods.ByName("ListPublishSpecs")),
		connect.WithHandlerOptions(opts...),
	)
	registryServiceOCICatalogHandler := connect.NewUnaryHandler(
		RegistryServiceOCICatalogProcedure,
		svc.OCICatalog,
		connect.WithSchema(registryServiceMethods.ByName("OCICatalog")),
		connect.WithHandlerOptions(opts...),
	)
	registryServiceSetPackageVisibilityHandler := connect.NewUnaryHandler(
		RegistryServiceSetPackageVisibilityProcedure,
		svc.SetPackageVisibility,
		connect.WithSchema(registryServiceMethods.ByName("SetPackageVisibility")),
		connect.WithHandlerOptions(opts...),
	)
	return "/easylab.v1.RegistryService/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case RegistryServiceListPackageTypesProcedure:
			registryServiceListPackageTypesHandler.ServeHTTP(w, r)
		case RegistryServiceListPackagesProcedure:
			registryServiceListPackagesHandler.ServeHTTP(w, r)
		case RegistryServicePackageVersionsProcedure:
			registryServicePackageVersionsHandler.ServeHTTP(w, r)
		case RegistryServiceDeletePackageProcedure:
			registryServiceDeletePackageHandler.ServeHTTP(w, r)
		case RegistryServiceDeletePackageVersionProcedure:
			registryServiceDeletePackageVersionHandler.ServeHTTP(w, r)
		case RegistryServiceListPublishSpecsProcedure:
			registryServiceListPublishSpecsHandler.ServeHTTP(w, r)
		case RegistryServiceOCICatalogProcedure:
			registryServiceOCICatalogHandler.ServeHTTP(w, r)
		case RegistryServiceSetPackageVisibilityProcedure:
			registryServiceSetPackageVisibilityHandler.ServeHTTP(w, r)
		default:
			http.NotFound(w, r)
		}
	})
}

